export class UserOrderModel {
    constructor(emitter) {
        this.UserOrderData = {
            payment: undefined,
            address: '',
            email: '',
            phone: '',
            items: [],
            total: 0,
        };
        this.emitter = emitter;
    }
    setField(field, value) {
        this.UserOrderData[field] = value;
    }
    getField(field) {
        return this.UserOrderData[field];
    }
    validate(field) {
        const value = this.UserOrderData[field];
        let isValid = true;
        if (typeof value === 'string' && !value.trim()) {
            isValid = false;
        }
        if (!isValid) {
            this.emitter.emit('order:error', {
                field,
                message: 'Необходимо указать адрес',
            });
        }
        return isValid;
    }
    prepareOrder() {
        const requiredFields = [
            'address',
            'email',
            'phone',
            'payment',
        ];
        let isFormValid = true;
        // Валидация текстовых полей
        for (const field of requiredFields) {
            if (!this.validate(field)) {
                isFormValid = false;
            }
        }
        // Валидация продуктов
        const products = this.UserOrderData.items;
        if (!Array.isArray(products) || products.length === 0) {
            this.emitter.emit('order:error', {
                field: 'items',
                message: 'Корзина пуста',
            });
            isFormValid = false;
        }
        else {
            for (const product of products) {
                const hasAllFields = Object.values(product).every((value) => value !== null && value !== undefined);
                if (!hasAllFields) {
                    this.emitter.emit('order:error', {
                        field: 'products',
                    });
                    isFormValid = false;
                    break;
                }
            }
        }
        if (isFormValid) {
            this.emitter.emit('order:ready', this.UserOrderData);
        }
    }
    setItems(items) {
        this.UserOrderData.items = items.map((item) => item.id);
    }
    setTotal(total) {
        this.UserOrderData.total = total;
    }
    get data() {
        return this.UserOrderData;
    }
    clear() {
        this.UserOrderData = {
            address: '',
            email: '',
            phone: '',
            payment: null,
            items: [],
            total: 0,
        };
    }
}
