export class CardModel {
    constructor(initialItems) {
        this._items = [];
        this._items = initialItems !== null && initialItems !== void 0 ? initialItems : [];
    }
    getItemById(id) {
        return this._items.find((item) => item.id === id);
    }
    get items() {
        return this._items;
    }
    set items(products) {
        this._items = products;
    }
}
