// Хорошая практика даже простые типы выносить в алиасы
/**
 * Брокер событий, классическая реализация
 * В расширенных вариантах есть возможность подписаться на все события
 * или слушать события по шаблону например
 */
export class EventEmitter {
    constructor() {
        this._events = new Map();
    }
    /**
     * Установить обработчик на событие
     */
    on(eventName, callback) {
        if (!this._events.has(eventName)) {
            this._events.set(eventName, new Set());
        }
        this._events.get(eventName).add(callback);
    }
    /**
     * Снять обработчик с события
     */
    off(eventName, callback) {
        const subs = this._events.get(eventName);
        if (subs) {
            subs.delete(callback);
            if (subs.size === 0) {
                this._events.delete(eventName);
            }
        }
    }
    /**
     * Инициировать событие с данными
     */
    emit(eventName, data) {
        for (const [name, subscribers] of this._events.entries()) {
            const match = name === '*' ||
                (typeof name === 'string' && name === eventName) ||
                (name instanceof RegExp && name.test(eventName));
            if (match) {
                subscribers.forEach((callback) => {
                    callback(name === '*' ? { eventName, data } : data);
                });
            }
        }
    }
    /**
     * Слушать все события
     */
    onAll(callback) {
        this.on('*', callback);
    }
    /**
     * Сбросить все обработчики
     */
    offAll() {
        this._events.clear();
    }
    /**
     * Создать функцию-триггер
     */
    trigger(eventName, context) {
        return (event = {}) => {
            this.emit(eventName, Object.assign(Object.assign({}, event), (context || {})));
        };
    }
}
export const eventBus = new EventEmitter();
