import { CDN_URL } from "../../utils/constants";
import { Api } from "../base/api";
export class ApiClient extends Api {
    constructor(baseUrl, options = {}) {
        super(baseUrl, options);
    }
    async getProducts() {
        const response = await this.get('/product');
        return response.items.map((item) => (Object.assign(Object.assign({}, item), { image: item.image ? `${CDN_URL}/${item.image}` : null })));
    }
    async createOrder(order) {
        await this.post('/order', order);
    }
}
