export class ModalBasket {
    constructor(template, emitter) {
        this.basketTemplate = template;
        this.emitter = emitter;
        const fragment = this.basketTemplate.content.cloneNode(true);
        this.basketElement = fragment.querySelector('.basket');
        this.submitButton = this.basketElement.querySelector('.basket__button');
        this.listContainer = this.basketElement.querySelector('.basket__list');
        this.submitButton.addEventListener('click', () => {
            this.emitter.emit('submit:click');
        });
    }
    render() {
        return this.basketElement;
    }
    setItems(items) {
        const list = this.listContainer;
        list.innerHTML = '';
        items.forEach((item) => {
            list.appendChild(item);
        });
        if (items.length > 0) {
            this.submitButton.removeAttribute('disabled');
        }
        else {
            this.submitButton.setAttribute('disabled', 'true');
        }
    }
    setTotal(total) {
        const totalElement = this.basketElement.querySelector('.basket__price');
        totalElement.textContent = `${total} синапсов`;
    }
}
