export class Basket {
    constructor(card) {
        this._total = 0;
        this._items = [];
        this._cardData = card;
    }
    get items() {
        return this._items;
    }
    get total() {
        return this._total;
    }
    getProducts() {
        return this._items;
    }
    addItem(itemId) {
        const product = this._cardData.getItemById(itemId);
        if (!product) {
            throw new Error(`Product with ID ${itemId} not found`);
        }
        else {
            this._items.push(product);
        }
        this.updateTotal();
    }
    deleteItem(itemId) {
        this._items = this._items.filter((item) => item.id !== itemId);
        this.updateTotal();
    }
    clearList() {
        this._items = [];
    }
    updateTotal() {
        this._total = this._items.reduce((sum, item) => sum + (item.price || 0), 0);
    }
}
