export class ModalSuccess {
    constructor(template, emitter) {
        this.emitter = emitter;
        this.template = template;
        this.element = this.template.content.firstElementChild.cloneNode(true);
    }
    renderSuccessModal(total) {
        const description = this.element.querySelector('.order-success__description');
        if (description) {
            description.textContent = `Списано ${total} синапсов`;
        }
        const closeButton = this.element.querySelector('.order-success__close');
        if (closeButton) {
            closeButton.addEventListener('click', () => {
                this.emitter.emit('modal:close');
            });
        }
        return this.element;
    }
}
