// src/utils/routing.ts
export class GitHubPagesRouter {
    constructor() {
        this.basePath = '';
        this.detectBasePath();
    }
    static getInstance() {
        if (!GitHubPagesRouter.instance) {
            GitHubPagesRouter.instance = new GitHubPagesRouter();
        }
        return GitHubPagesRouter.instance;
    }
    detectBasePath() {
        // Определяем базовый путь
        if (window.location.hostname.includes('github.io')) {
            // Извлекаем путь репозитория из URL
            const path = window.location.pathname;
            const parts = path.split('/');
            if (parts.length > 2) {
                this.basePath = '/' + parts[1] + '/';
            }
        }
        console.log('Detected base path:', this.basePath);
    }
    getBasePath() {
        return this.basePath;
    }
    fixHrefs() {
        // Фиксим все ссылки
        document.querySelectorAll('a').forEach(link => {
            const href = link.getAttribute('href');
            if (href && href.startsWith('/') && !href.startsWith('//')) {
                link.setAttribute('href', this.basePath + href.substring(1));
            }
        });
        // Фиксим все event listeners
        document.addEventListener('click', (e) => {
            const target = e.target;
            const link = target.closest('a');
            if (link && link.href.includes(window.location.host)) {
                const href = link.getAttribute('href');
                if (href && !href.startsWith(this.basePath) && href.startsWith('/')) {
                    e.preventDefault();
                    window.location.href = this.basePath + href.substring(1);
                }
            }
        });
    }
    navigate(path) {
        window.location.href = this.basePath + (path.startsWith('/') ? path.substring(1) : path);
    }
}
